"""Decide which files in a project tree are excluded by its .packignore files."""

import os
import re


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    files = []
    rules_by_dir = {}
    for dirpath, dirnames, filenames in os.walk(root):
        rel = os.path.relpath(dirpath, root).replace(os.sep, "/")
        if rel == ".":
            rel = ""
        if rel == "" and ".git" in dirnames:
            dirnames.remove(".git")
        if ".packignore" in filenames:
            with open(os.path.join(dirpath, ".packignore"), newline="") as f:
                content = f.read()
            rules_by_dir[rel] = _parse(content)
        for name in filenames:
            files.append(f"{rel}/{name}" if rel else name)

    ignored = []
    for path in files:
        if _is_ignored(path, False, rules_by_dir):
            ignored.append(path)
    return sorted(ignored)


def _is_ignored(path, is_dir, rules_by_dir):
    parts = path.split("/")
    for i in range(1, len(parts)):
        ancestor = "/".join(parts[:i])
        if _excluded_single(ancestor, True, rules_by_dir):
            return True
    return _excluded_single(path, is_dir, rules_by_dir)


def _excluded_single(path, is_dir, rules_by_dir):
    state = False
    ancestors = sorted(
        (d for d in rules_by_dir if d == "" or path == d or path.startswith(d + "/")),
        key=lambda d: (len(d), d),
    )
    for anc in ancestors:
        local = path if anc == "" else path[len(anc) + 1:]
        if not local:
            continue
        for rule in rules_by_dir[anc]:
            if _match(rule, local, is_dir):
                state = not rule.negated
    return state


class _Rule:
    __slots__ = ("negated", "dir_only", "regex")

    def __init__(self, negated, dir_only, regex):
        self.negated = negated
        self.dir_only = dir_only
        self.regex = regex


def _parse(content):
    rules = []
    for line in content.splitlines():
        rule = _parse_line(line)
        if rule is not None:
            rules.append(rule)
    return rules


def _parse_line(line):
    # Strip trailing unescaped whitespace.
    s = line
    end = len(s)
    while end > 0 and s[end - 1] in " \t":
        if end >= 2 and s[end - 2] == "\\":
            break
        end -= 1
    s = s[:end]

    if not s:
        return None
    if s[0] == "#":
        return None

    negated = False
    if s[0] == "!":
        negated = True
        s = s[1:]
    elif s.startswith("\\!"):
        s = s[1:]
    elif s.startswith("\\#"):
        s = s[1:]

    dir_only = False
    if s.endswith("/"):
        dir_only = True
        s = s[:-1]

    if not s:
        return None

    # Anchored if contains "/" anywhere in the (now cleaned) pattern.
    anchored = "/" in s
    if s.startswith("/"):
        s = s[1:]
    regex = _translate(s, anchored)
    return _Rule(negated, dir_only, regex)


def _translate(pattern, anchored):
    """Translate a glob pattern to an anchored regex."""
    i = 0
    n = len(pattern)
    out = []
    while i < n:
        c = pattern[i]
        if c == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                # ** sequence
                prev_slash = (i == 0) or (pattern[i - 1] == "/")
                next_slash = (i + 2 < n and pattern[i + 2] == "/")
                at_end = (i + 2 == n)
                if prev_slash and next_slash:
                    # /**/
                    out.append("(?:.*/)?")
                    i += 3
                elif prev_slash and at_end:
                    # trailing /**
                    out.append(".*")
                    i += 2
                elif i == 0 and next_slash:
                    # leading **/
                    out.append("(?:.*/)?")
                    i += 3
                else:
                    # ** not between slashes -> treat as *
                    out.append("[^/]*")
                    i += 2
            else:
                out.append("[^/]*")
                i += 1
        elif c == "?":
            out.append("[^/]")
            i += 1
        elif c == "\\" and i + 1 < n:
            out.append(re.escape(pattern[i + 1]))
            i += 2
        elif c == "[":
            # char class
            j = i + 1
            if j < n and pattern[j] == "!":
                j += 1
            if j < n and pattern[j] == "]":
                j += 1
            while j < n and pattern[j] != "]":
                j += 1
            if j >= n:
                out.append(re.escape(c))
                i += 1
            else:
                cls = pattern[i + 1:j]
                if cls.startswith("!"):
                    cls = "^" + cls[1:]
                out.append("[" + cls + "]")
                i = j + 1
        else:
            out.append(re.escape(c))
            i += 1

    body = "".join(out)
    if anchored:
        return re.compile(r"\A" + body + r"\Z")
    return re.compile(r"(?:\A|/)" + body + r"\Z")


def _match(rule, path, is_dir):
    if rule.dir_only and not is_dir:
        return False
    return bool(rule.regex.search(path))

