    files = []
    rules_by_dir = {}
    for dirpath, dirnames, filenames in os.walk(root):
        rel = os.path.relpath(dirpath, root).replace(os.sep, "/")
        if rel == ".":
            rel = ""
        if rel == "" and ".git" in dirnames:
            dirnames.remove(".git")
        if ".packignore" in filenames:
            with open(os.path.join(dirpath, ".packignore"), newline="") as f:
                content = f.read()
            rules_by_dir[rel] = _parse(content)
        for name in filenames:
            files.append(f"{rel}/{name}" if rel else name)

    out = []
    for p in files:
        if _file_ignored(p, rules_by_dir):
            out.append(p)
    return sorted(out)


def _file_ignored(path, rules_by_dir):
    parts = path.split("/")
    for i in range(1, len(parts)):
        if _path_state("/".join(parts[:i]), True, rules_by_dir) == 1:
            return True
    return _path_state(path, False, rules_by_dir) == 1


def _path_state(path, is_dir, rules_by_dir):
    """Return 1 if ignored, -1 if explicitly re-included, 0 if no match."""
    parts = path.split("/")
    for i in range(len(parts) - 1, -1, -1):
        anc = "/".join(parts[:i])
        if anc not in rules_by_dir:
            continue
        local = path if anc == "" else path[len(anc) + 1:]
        if not local:
            continue
        matches = []
        for idx, rule in enumerate(rules_by_dir[anc]):
            if _match(rule, local, is_dir):
                matches.append((rule.spec, idx, rule))
        if matches:
            matches.sort()
            winner = matches[-1][2]
            return -1 if winner.negated else 1
    return 0


class _Rule:
    __slots__ = ("negated", "dir_only", "regex", "spec")

    def __init__(self, negated, dir_only, regex, spec):
        self.negated = negated
        self.dir_only = dir_only
        self.regex = regex
        self.spec = spec


def _parse(content):
    rules = []
    for line in content.splitlines():
        rule = _parse_line(line)
        if rule is not None:
            rules.append(rule)
    return rules


def _parse_line(line):
    s = line
    while s and s[-1] in " \t\r":
        s = s[:-1]
    if not s or s[0] == "#":
        return None

    negated = False
    if s[0] == "!":
        negated = True
        s = s[1:]
    if not s:
        return None

    dir_only = False
    if s.endswith("/"):
        dir_only = True
        s = s[:-1]
    if not s:
        return None

    anchored = "/" in s
    if s.startswith("/"):
        s = s[1:]
    if not s:
        return None

    body = _translate(s)
    if anchored:
        regex = re.compile(r"\A" + body + r"\Z")
    else:
        regex = re.compile(r"(?:\A|/)" + body + r"\Z")
    spec = sum(1 for c in s if c not in "*?/")
    return _Rule(negated, dir_only, regex, spec)


def _translate(pattern):
    i = 0
    n = len(pattern)
    out = []
    while i < n:
        c = pattern[i]
        if c == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                prev_slash = (i == 0) or (pattern[i - 1] == "/")
                at_end = (i + 2 == n)
                next_slash = (i + 2 < n and pattern[i + 2] == "/")
