"""Randomized fuzz testing of my ignore.py against packignore."""
import os
import random
import shutil
import subprocess
import sys
import tempfile

sys.path.insert(0, "/tmp/work")
sys.path.insert(0, "/work/repo")
from difftest import packignore_run

import importlib
import snapshot.ignore as m


def my_run(root):
    importlib.reload(m)
    return m.ignored_files(root)


def rand_name(rng, allow_leading_dot=True):
    chars = "abcde"
    length = rng.randint(1, 4)
    name = "".join(rng.choice(chars) for _ in range(length))
    # Occasionally add extension
    if rng.random() < 0.4:
        ext = rng.choice(["txt", "log", "tmp", "py", "o"])
        name = f"{name}.{ext}"
    return name


def rand_tree(rng, max_files=15, max_depth=3):
    """Return dict path -> content."""
    tree = {}
    files = rng.randint(1, max_files)
    for _ in range(files):
        depth = rng.randint(0, max_depth)
        parts = [rand_name(rng) for _ in range(depth)]
        parts.append(rand_name(rng))
        path = "/".join(parts)
        tree[path] = ""
    return tree


def rand_pattern(rng):
    base = []
    length = rng.randint(1, 5)
    for _ in range(length):
        tok = rng.choices(
            ["lit", "star", "qmark", "dstar", "slash"],
            weights=[6, 3, 1, 2, 2],
            k=1,
        )[0]
        if tok == "lit":
            base.append(rng.choice("abcde"))
        elif tok == "star":
            base.append("*")
        elif tok == "qmark":
            base.append("?")
        elif tok == "dstar":
            base.append("**")
        elif tok == "slash":
            base.append("/")
    pat = "".join(base)
    # Collapse unlikely sequences
    pat = pat.replace("////", "/").replace("///", "/").replace("//", "/")
    if not pat:
        pat = "a"
    # Occasional negation
    if rng.random() < 0.3:
        pat = "!" + pat
    # Occasional trailing /
    if rng.random() < 0.2 and not pat.endswith("/"):
        pat = pat + "/"
    return pat


def rand_packignore(rng, nrules=5):
    rules = []
    for _ in range(rng.randint(0, nrules)):
        rules.append(rand_pattern(rng))
    return "\n".join(rules) + ("\n" if rules else "")


def run_fuzz(seed, root_dir):
    rng = random.Random(seed)
    tree = rand_tree(rng)
    # Add .packignore(s)
    tree[".packignore"] = rand_packignore(rng)
    # Maybe nested .packignore
    if rng.random() < 0.5:
        dirs = {p.rsplit("/", 1)[0] for p in tree if "/" in p}
        if dirs:
            d = rng.choice(list(dirs))
            tree[f"{d}/.packignore"] = rand_packignore(rng)

    # Build tree
    for path, content in tree.items():
        full = os.path.join(root_dir, path)
        parent = os.path.dirname(full)
        if parent and parent != root_dir:
            os.makedirs(parent, exist_ok=True)
        if os.path.isdir(full):
            continue
        with open(full, "w") as f:
            f.write(content)

    got_pack = packignore_run(root_dir)
    got_mine = my_run(root_dir)
    return got_pack, got_mine, tree


def main(count=200, start=0):
    passed = 0
    fails = []
    for seed in range(start, start + count):
        with tempfile.TemporaryDirectory() as root:
            try:
                p, m, tree = run_fuzz(seed, root)
            except Exception as e:
                fails.append((seed, "exception", str(e), None))
                continue
            if p == m:
                passed += 1
            else:
                fails.append((seed, "mismatch", p, m, tree))
                if len(fails) >= 8:
                    break
    print(f"Passed {passed}/{count}")
    for f in fails[:5]:
        seed = f[0]
        kind = f[1]
        print(f"\n--- Seed {seed} ({kind}) ---")
        if kind == "mismatch":
            print(f"  tree: {f[4]}")
            print(f"  pack: {f[2]}")
            print(f"  mine: {f[3]}")
            print(f"  only pack: {sorted(set(f[2]) - set(f[3]))}")
            print(f"  only mine: {sorted(set(f[3]) - set(f[2]))}")
        else:
            print(f"  {f[2]}")


if __name__ == "__main__":
    count = int(sys.argv[1]) if len(sys.argv) > 1 else 100
    start = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    main(count, start)

